import {listDocuments,getDocument,saveReview,REVIEW_STATUSES,CHECKS,catalogueLinks,fitsLink} from './cell-documents-store.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>new Date(value).toLocaleString('en-AU',{timeZone:'UTC'})+' UTC';
const image=value=>/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(value||'')?value:'';
const statusOptions=selected=>Object.entries(REVIEW_STATUSES).map(([key,label])=>'<option value="'+key+'" '+(selected===key?'selected':'')+'>'+esc(label)+'</option>').join('');
export function documentsMarkup(){return '<main id="main" class="shell documents-page"><div id="documents-content"><p role="status">Loading saved cells…</p></div></main>';}
function download(records,name){const blob=new Blob([JSON.stringify({format:'SATE cell notebook',version:1,exportedAt:new Date().toISOString(),cells:records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function sourceHtml(record,layer,side,width=.2){
 const obs=layer.observations?.[side],label=(side==='left'?'L':'R');
 if(!obs)return '<p>'+label+': '+esc(layer.status?.[side]||'No observation saved')+'</p>';
 const href=fitsLink(obs.path,record,width),sources=(obs.sources||[]).map(source=>{const link=fitsLink(source.path,record,width);return link?'<a target="_blank" rel="noreferrer" href="'+esc(link)+'">'+esc(source.id)+'</a>':'';}).join(' · ');
 return '<p><b>'+label+'</b> '+esc(date(obs.date))+' · '+esc(Number(obs.wavelength).toFixed(3))+' µm<br><span>'+esc(obs.id)+' · '+esc(obs.band)+'</span> '+(href?'<a target="_blank" rel="noreferrer" href="'+esc(href)+'">FITS ↗</a>':'')+(obs.combined?'<br>Combined exposure · '+esc(obs.members)+' members'+(sources?'<br>'+sources:''):'')+'</p>';
}
function snapshotHtml(record,snapshot,index){
 const previews=['left','right',...(snapshot.previews.comparison?['comparison']:[])].filter(side=>snapshot.previews[side]).map(side=>'<figure><img src="'+image(snapshot.previews[side])+'" alt="Saved '+side+' view of cell '+record.cellId+'"><figcaption>'+({left:'Left image',right:'Right image',comparison:'Comparison — '+snapshot.compareOpacity+'% right image'})[side]+'</figcaption></figure>').join('');
 return '<details class="doc-snapshot" '+(!index?'open':'')+'><summary>Observation '+(record.snapshots.length-index)+' · '+esc(date(snapshot.savedAt))+'</summary><div class="doc-snapshot-body"><div class="doc-previews">'+previews+'</div><a class="doc-button" href="'+esc(snapshot.viewerUrl)+'">Reopen this view ↗</a><div class="doc-sources">'+snapshot.layers.map(layer=>'<section><h3>Layer '+layer.number+' · '+esc(layer.mode==='all'?'All wavelengths':layer.mode==='mix'?'Mixed wavelengths':Number(layer.wavelength).toFixed(3)+' µm')+'</h3><p class="doc-muted">'+(layer.visible?'Visible':'Hidden')+' · '+Math.round(layer.opacity*100)+'% opacity · '+(layer.hue===null?'Grayscale':'Hue '+layer.hue+'°')+'</p>'+sourceHtml(record,layer,'left',snapshot.fieldDegrees)+(snapshot.previews.right?sourceHtml(record,layer,'right',snapshot.fieldDegrees):'')+'</section>').join('')+'</div><details class="doc-settings"><summary>Saved image settings</summary><pre>'+esc(JSON.stringify(snapshot.display,null,2))+'</pre></details></div></details>';
}
function detailHtml(record){
 const links=catalogueLinks(record.candidate),last=record.snapshots[0];
 return '<a class="doc-back" href="/saved-cells/">← Saved cells</a><div class="doc-heading"><div><p class="eyebrow">Observation notebook</p><h1 id="doc-title">'+esc(record.title)+'</h1><p class="doc-muted">Cell '+record.cellId+' · RA '+record.ra.toFixed(5)+'° · Dec '+record.dec.toFixed(5)+'°</p><span class="doc-status" id="doc-status">'+esc(REVIEW_STATUSES[record.status])+'</span></div><div class="doc-actions"><a class="doc-button" href="'+esc(last.viewerUrl)+'">Open cell ↗</a><button class="doc-button secondary" id="doc-export">Export record</button></div></div><div class="doc-detail-grid"><section class="doc-panel"><h2>Review this cell</h2><form id="doc-review"><label>Title<input name="title" value="'+esc(record.title)+'" maxlength="160" required></label><label>Review status<select name="status">'+statusOptions(record.status)+'</select></label><label>What did you notice?<textarea name="notes" rows="6" maxlength="20000" placeholder="Describe the object, changes across dates or wavelengths, and what needs checking.">'+esc(record.notes)+'</textarea></label><fieldset><legend>Candidate position</legend><p class="doc-muted">Starts at the cell centre. Enter the suspected object’s coordinates to narrow your catalogue search.</p><div class="doc-coordinate-fields"><label>RA (degrees)<input name="ra" type="number" min="0" max="359.99999999" step="any" value="'+record.candidate.ra+'" required></label><label>Dec (degrees)<input name="dec" type="number" min="-90" max="90" step="any" value="'+record.candidate.dec+'" required></label><label>Radius (arcsec)<input name="radius" type="number" min="1" max="3600" step="any" value="'+record.candidate.radius+'" required></label></div><div class="doc-actions"><a id="doc-simbad" class="doc-button secondary" target="_blank" rel="noreferrer" href="'+esc(links.simbad)+'">Search SIMBAD ↗</a><a id="doc-vizier" class="doc-button secondary" target="_blank" rel="noreferrer" href="'+esc(links.vizier)+'">Search VizieR ↗</a></div></fieldset><fieldset><legend>Evidence checks</legend>'+Object.entries(CHECKS).map(([key,label])=>'<label class="doc-check"><input name="'+key+'" type="checkbox" '+(record.checks[key]?'checked':'')+'>'+label+'</label>').join('')+'</fieldset><label>Catalogue IDs and evidence links<textarea name="reference" rows="3" maxlength="5000" placeholder="Record matches, search results, links, and follow-up evidence.">'+esc(record.reference)+'</textarea></label><p class="doc-muted">No catalogue match is a lead, not confirmation of a new object. Check other surveys, observation dates and imaging artifacts before reporting a candidate.</p><button class="doc-button" type="submit">Save review</button><p id="doc-save-status" role="status"></p></form></section><section class="doc-evidence"><h2>Saved observations <span class="doc-count">'+record.snapshots.length+'</span></h2><p class="doc-muted">Each save keeps image previews, dates, wavelengths, layer settings and source records. FITS links open the original measurements; full FITS files are not stored in this notebook.</p>'+record.snapshots.map((s,i)=>snapshotHtml(record,s,i)).join('')+'</section></div><p class="doc-storage-note">Saved on this device in this browser. Export your record for a backup or to share it. Clearing site data removes local records.</p>';
}
export function mountDocuments(){
 const root=document.querySelector('#documents-content');let dead=false,record;
 const key=new URLSearchParams(location.search).get('cell');
 async function list(){
  const records=await listDocuments();if(dead)return;
  root.innerHTML='<div class="doc-heading"><div><p class="eyebrow">Observation notebook</p><h1>Saved cells</h1><p class="doc-muted">Keep observations, compare evidence, and track candidates over time.</p></div><button class="doc-button secondary" id="doc-export-all" '+(!records.length?'disabled':'')+'>Export notebook</button></div><p class="doc-storage-note">Saved on this device in this browser. Export a backup to keep your work if site data is cleared.</p><div class="doc-filters"><label>Find a cell<input id="doc-search" type="search" placeholder="Cell number, title or notes"></label><label>Status<select id="doc-filter"><option value="">All statuses</option>'+statusOptions('')+'</select></label></div><p id="doc-results" role="status"></p><div id="doc-list" class="doc-list"></div>';
  function filter(){const query=root.querySelector('#doc-search').value.trim().toLowerCase(),status=root.querySelector('#doc-filter').value,filtered=records.filter(r=>(!status||r.status===status)&&[r.cellId,r.title,r.notes].join(' ').toLowerCase().includes(query));root.querySelector('#doc-results').textContent=filtered.length+' saved cell'+(filtered.length===1?'':'s');root.querySelector('#doc-list').innerHTML=filtered.length?filtered.map(r=>'<a class="doc-card" href="/saved-cells/?cell='+encodeURIComponent(r.key)+'"><img src="'+image(r.snapshots[0].previews.left)+'" alt="Saved view of cell '+r.cellId+'"><div><h2>'+esc(r.title)+'</h2><span class="doc-status">'+esc(REVIEW_STATUSES[r.status])+'</span><p>Cell '+r.cellId+' · '+r.snapshots.length+' saved observation'+(r.snapshots.length===1?'':'s')+'</p><p class="doc-muted">Updated '+esc(date(r.updatedAt))+'</p></div><span aria-hidden="true">↗</span></a>').join(''):'<div class="doc-empty"><h2>'+(!records.length?'Start documenting your observations':'No matching cells')+'</h2><p>'+(!records.length?'Open a cell in Explore and choose Document cell to save your current view.':'Try a different search or review status.')+'</p><a class="doc-button" href="/explore/">Explore the sky ↗</a></div>';}
  root.querySelector('#doc-search').oninput=filter;root.querySelector('#doc-filter').onchange=filter;root.querySelector('#doc-export-all').onclick=()=>download(records,'sate-cell-notebook.json');filter();
 }
 async function detail(){
  record=await getDocument(key);if(dead)return;if(!record){root.innerHTML='<h1>Saved cell not found</h1><a href="/saved-cells/">Return to saved cells</a>';return;}
  root.innerHTML=detailHtml(record);const form=root.querySelector('#doc-review');
  const position=()=>({ra:form.elements.ra.value,dec:form.elements.dec.value,radius:form.elements.radius.value});
  form.oninput=()=>{root.querySelector('#doc-save-status').textContent='Unsaved changes';try{const links=catalogueLinks(position());for(const name of ['simbad','vizier']){const link=root.querySelector('#doc-'+name);link.href=links[name];link.removeAttribute('aria-disabled');}}catch{for(const name of ['simbad','vizier']){const link=root.querySelector('#doc-'+name);link.removeAttribute('href');link.setAttribute('aria-disabled','true');}}};
  form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]'),message=root.querySelector('#doc-save-status');button.disabled=true;message.textContent='Saving…';try{const patch={title:form.elements.title.value,status:form.elements.status.value,notes:form.elements.notes.value,reference:form.elements.reference.value,candidate:position(),checks:Object.fromEntries(Object.keys(CHECKS).map(k=>[k,form.elements[k].checked]))};record=await saveReview(key,patch);if(dead)return;root.querySelector('#doc-title').textContent=record.title;root.querySelector('#doc-status').textContent=REVIEW_STATUSES[record.status];message.textContent='Review saved';}catch(error){if(!dead)message.textContent=error.message;}finally{if(!dead)button.disabled=false;}};
  root.querySelector('#doc-export').onclick=()=>download([record],'sate-cell-'+record.cellId+'.json');
 }
 (key?detail():list()).catch(error=>{if(!dead)root.innerHTML='<h1>Saved cells unavailable</h1><p role="alert">'+esc(error.message)+'</p><a class="doc-button" href="/saved-cells/">Try again</a>';});
 return()=>{dead=true;};
}
